const match = String(msg.topic || '').match(/^station\/([1-3])\/data$/);
if (!match) return null;

const id = Number(match[1]);
let input = msg.payload;

if (typeof input === 'string') {
  try { input = JSON.parse(input); } catch (e) { return null; }
}
if (!input || typeof input !== 'object' || Array.isArray(input)) return null;

let stations = context.get('stations');
if (!stations) {
  stations = {};
  for (let i = 1; i <= 3; i++) {
    stations[i] = {
      id: i,
      status: 'UNKNOWN',
      connectionStatus: 'UNKNOWN',
      power: 0,
      energy: 0,
      temperature: null,
      soc: null,
      batteryCapacityKWh: null,
      fullIn: '--',
      faultCode: '',
      errorCode: null,
      errorMessage: null,
      sessionCode: null,
      lastSeen: 0,
      powerHistory: [],
      temperatureHistory: []
    };
  }
}

const s = stations[id];
const now = Date.now();
const wasOffline = s.connectionStatus === 'OFFLINE';
const events = [];

// HEARTBEAT: chi cap nhat trang thai ket noi
// Khong ghi de du lieu sac, SOC, cong suat, loi E1/E3.

if (input.heartbeat === true) {

  s.connectionStatus = 'ONLINE';
  s.lastSeen = now;

  // Chi xoa loi E2 do mat ket noi
  if (s.errorCode === 'E2') {
    s.errorCode = null;
    s.faultCode = '';
    s.errorMessage = null;

    if (s.status === 'FAULT') {
      s.status = 'AVAILABLE';
    }
  }

  const map = global.get('evStationMap') || {};
  const uuid = map[String(id)] || null;

  if (wasOffline) {
    events.push({
      station_id: uuid,
      stationNo: id,
      event_type: 'CONNECTION',
      event_code: 'ONLINE',
      title: 'Tram online lai',
      message: 'Nhan lai heartbeat MQTT',
      event_id: 'online-' + id + '-' + now
    });
  }

  stations[id] = s;

  context.set('stations', stations);
  global.set('evStations', stations);

  msg.payload = {
    stations: [stations[1], stations[2], stations[3]],
    updatedAt: now,
    _events: events,
    _stationNo: id
  };

  return msg;
}

// Status
const allowed = ['AVAILABLE', 'FREE', 'CHARGING', 'COMPLETED', 'FAULT'];
const incoming = String(input.status || input.operating_status || s.status || 'UNKNOWN').toUpperCase();
if (allowed.includes(incoming)) {
  s.status = incoming === 'FREE' ? 'AVAILABLE' : incoming;
}

// Power
if (input.power_kw !== undefined && Number.isFinite(Number(input.power_kw))) {
  s.power = Math.max(0, Number(input.power_kw));
} else if (input.power !== undefined && Number.isFinite(Number(input.power))) {
  const p = Number(input.power);
  s.power = p > 50 ? p / 1000 : p;
}

// Energy (chuyển về kWh)
if (input.energy_wh !== undefined && Number.isFinite(Number(input.energy_wh))) {
  s.energy = Math.max(0, Number(input.energy_wh)) / 1000;
} else if (input.energy !== undefined && Number.isFinite(Number(input.energy))) {
  const e = Number(input.energy);
  s.energy = e > 100 ? e / 1000 : e;
}

// Temperature
if (input.temperature !== undefined && input.temperature !== null && Number.isFinite(Number(input.temperature))) {
  s.temperature = Number(input.temperature);
} else if (input.temperature_c !== undefined && Number.isFinite(Number(input.temperature_c))) {
  s.temperature = Number(input.temperature_c);
}

// SOC & Capacity
if (input.soc !== undefined && input.soc !== null && Number.isFinite(Number(input.soc))) {
  s.soc = Math.min(100, Math.max(0, Number(input.soc)));
}
if (input.batteryCapacityKWh !== undefined && Number.isFinite(Number(input.batteryCapacityKWh))) {
  s.batteryCapacityKWh = Math.max(0, Number(input.batteryCapacityKWh));
}

// Session code
if (input.session_code || input.sessionCode) {
  s.sessionCode = String(input.session_code || input.sessionCode);
}

// ========== FAULT ==========
// Chỉ cập nhật lỗi khi telemetry GỬI RÕ fault_code / errorCode.
// Nếu field bị bỏ trống (undefined) → giữ nguyên E1/E3 đang tồn tại.
// Chỉ xóa lỗi khi nhận được chuỗi rỗng tường minh "" hoặc "NONE"/"OK"/"CLEAR".
const rawFault = input.fault_code ?? input.faultCode ?? input.errorCode;
if (rawFault !== undefined && rawFault !== null) {
  const fc = String(rawFault).toUpperCase().trim();
  if (fc && fc !== 'NONE' && fc !== 'OK' && fc !== 'CLEAR' && fc !== 'NULL') {
    s.faultCode = fc;
    s.errorCode = fc;
    if (fc === 'E1') s.errorMessage = 'QUÁ NHIỆT';
    else if (fc === 'E2') s.errorMessage = 'MẤT KẾT NỐI';
    else if (fc === 'E3') s.errorMessage = 'DỪNG KHẨN CẤP';
    else s.errorMessage = input.errorMessage || fc;
  } else {
    // Telemetry gửi rõ ràng là hết lỗi
    s.faultCode = '';
    s.errorCode = null;
    s.errorMessage = null;
  }
}
// Nếu rawFault === undefined → không đụng tới errorCode hiện tại (giữ E1/E3)
// ================================================================

// Tôn trọng Last Will OFFLINE từ ESP32/broker.
const reportedConnection = String(input.connection_status || '').toUpperCase();
if (reportedConnection === 'OFFLINE') {
  s.connectionStatus = 'OFFLINE';
  if (s.errorCode !== 'E1' && s.errorCode !== 'E3') {
    s.status = 'FAULT';
    s.faultCode = 'E2';
    s.errorCode = 'E2';
    s.errorMessage = 'DISCONNECTED';
  }
  s.power = 0;
} else {
  s.connectionStatus = 'ONLINE';
}
s.lastSeen = now;

// Lấy UUID để ghi sự kiện
const map = global.get('evStationMap') || {};
const uuid = map[String(id)] || null;

if (wasOffline) {
  events.push({
    station_id: uuid,
    stationNo: id,
    event_type: 'CONNECTION',
    event_code: 'ONLINE',
    title: 'Trạm online lại',
    message: 'Nhận lại telemetry MQTT',
    event_id: 'online-' + id + '-' + now
  });
}

if (s.status === 'FAULT' && s.errorCode && ['E1', 'E3'].includes(s.errorCode)) {
  events.push({
    station_id: uuid,
    stationNo: id,
    event_type: 'FAULT',
    event_code: s.errorCode,
    title: s.errorCode === 'E1' ? 'Quá nhiệt' : 'Dừng khẩn cấp',
    message: s.errorMessage || s.errorCode,
    event_id: 'fault-' + id + '-' + s.errorCode + '-' + Math.floor(now / 60000)
  });
}

// History
s.powerHistory.push({ time: now, value: s.power });
if (s.temperature !== null) s.temperatureHistory.push({ time: now, value: s.temperature });
s.powerHistory = s.powerHistory.slice(-30);
s.temperatureHistory = s.temperatureHistory.slice(-30);

// Full-in estimate
s.fullIn = '--';
if (s.status === 'CHARGING' && s.soc !== null && s.batteryCapacityKWh > 0 && s.power > 0 && s.soc < 100) {
  const remainingKWh = s.batteryCapacityKWh * (100 - s.soc) / 100;
  const minutes = Math.ceil(remainingKWh / s.power * 60);
  if (minutes < 60) s.fullIn = minutes + ' phút';
  else {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    s.fullIn = m ? h + ' giờ ' + m + ' phút' : h + ' giờ';
  }
}

stations[id] = s;
context.set('stations', stations);
global.set('evStations', stations);

msg.payload = {
  stations: [stations[1], stations[2], stations[3]],
  updatedAt: now,
  _events: events,
  _stationNo: id
};
return msg;

let stations = context.get('stations') || global.get('evStations') || {};
const now = Date.now();
let changed = false;
const events = [];

for (let i = 1; i <= 3; i++) {
  const s = stations[i];
  if (!s || !s.lastSeen) continue;
  const offline = (now - s.lastSeen > 90000);
  if (offline && s.connectionStatus !== 'OFFLINE') {
    s.connectionStatus = 'OFFLINE';
    // Không ghi đè E1/E3
    if (s.status !== 'FAULT' || s.errorCode === 'E2' || !s.errorCode) {
      s.status = 'FAULT';
      s.faultCode = 'E2';
      s.errorCode = 'E2';
      s.errorMessage = 'DISCONNECTED – no telemetry > 90s';
    }
    s.power = 0;
    changed = true;
    events.push({
      stationNo: i,
      event_type: 'CONNECTION',
      event_code: 'E2',
      title: 'Trạm offline',
      message: 'Mất telemetry quá 90 giây',
      event_id: 'e2-' + i + '-' + Math.floor(now / 90000)
    });
  }
}
if (!changed) return null;
context.set('stations', stations);
global.set('evStations', stations);
msg.payload = { stations: [stations[1], stations[2], stations[3]], updatedAt: now, _events: events };
return msg;

// ================================================
// CHUẨN BỊ GHI STATION_EVENTS
// Hỗ trợ:
// - Sự kiện ONLINE
// - Sự kiện E1: OVERHEAT
// - Sự kiện E2: DISCONNECTED
// - Sự kiện E3: EMERGENCY STOP
// ================================================

// 1. Lấy dữ liệu sự kiện
const payload = msg.payload;

let incoming = [];

if (Array.isArray(payload)) {
    // Trường hợp payload là một mảng sự kiện
    incoming = payload;

} else if (payload && Array.isArray(payload._events)) {
    // Trường hợp telemetry/offline gửi object chứa _events
    incoming = payload._events;

} else if (payload && payload.event_type) {
    // Trường hợp chỉ có một sự kiện đơn
    incoming = [payload];
}

// Không có sự kiện thì dừng
if (!incoming.length) {
    return null;
}

// 2. Lấy bản đồ stationNo -> UUID
const map = global.get('evStationMap') || {};

// 3. Chuyển sự kiện thành dữ liệu phù hợp Supabase
const rows = [];

for (const ev of incoming) {

    if (!ev || typeof ev !== 'object') {
        continue;
    }

    // Ưu tiên UUID có sẵn trong sự kiện
    let stationUUID = ev.station_id || null;

    // Nếu chưa có UUID thì tìm bằng stationNo
    if (!stationUUID && ev.stationNo !== undefined) {
        stationUUID = map[String(ev.stationNo)] || null;
    }

    // Không có UUID hợp lệ thì bỏ qua
    if (!stationUUID) {
        node.warn(
            'Không tìm thấy station_id cho sự kiện: ' +
            JSON.stringify(ev)
        );
        continue;
    }

    rows.push({
        station_id: stationUUID,

        event_type: ev.event_type || 'FAULT',

        event_code: ev.event_code || '',

        event_id: ev.event_id || null,

        title: ev.title || '',

        message: ev.message || '',

        payload: ev.payload || ev,

        created_at: ev.created_at || new Date().toISOString()
    });
}

// Không còn sự kiện hợp lệ
if (!rows.length) {
    return null;
}

// 4. Lấy thông tin Supabase từ Environment Variables
const baseUrl = String(env.get('SUPABASE_URL') || '')
    .replace(/\/+$/, '')
    .replace(/\/rest\/v1$/i, '');

const key = env.get('SUPABASE_SERVICE_ROLE_KEY');

if (!baseUrl || !key) {
    node.error(
        'Thiếu SUPABASE_URL hoặc SUPABASE_SERVICE_ROLE_KEY',
        msg
    );
    return null;
}

// 5. Chuẩn bị HTTP POST đến Supabase
msg.method = 'POST';

msg.url = baseUrl + '/rest/v1/station_events';

msg.headers = {
    'apikey': key,
    'Authorization': 'Bearer ' + key,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal,resolution=ignore-duplicates'
};

msg.payload = rows;

msg._loai = 'station_events';

return msg;

const stations = (msg.payload && msg.payload.stations) || [];
if (!stations.length) return null;

const map = global.get('evStationMap') || {};
const baseUrl = String(env.get('SUPABASE_URL') || '').replace(/\/+$/, '').replace(/\/rest\/v1$/i, '');
const key = env.get('SUPABASE_SERVICE_ROLE_KEY');
if (!baseUrl || !key) return null;

const rows = [];
const now = new Date().toISOString();

for (const s of stations) {
  if (!s || !s.id) continue;
  const uuid = map[String(s.id)];
  if (!uuid) continue;

  rows.push({
    station_id: uuid,
    operating_status: s.status || 'UNKNOWN',
    connection_status: ['NOT_CONNECTED', 'ONLINE', 'OFFLINE', 'UNKNOWN'].includes(String(s.connectionStatus || '').toUpperCase())
    ? String(s.connectionStatus || 'UNKNOWN').toUpperCase()
    : 'UNKNOWN',
    power_kw: Number(s.power) || 0,
    energy_wh: Math.round((Number(s.energy) || 0) * 1000),   // kWh → Wh
    temperature_c: s.temperature,
    soc: s.soc,
    fault_code: s.errorCode || s.faultCode || null,
    last_seen: s.lastSeen ? new Date(s.lastSeen).toISOString() : now,
    updated_at: now
  });
}

if (!rows.length) return null;

msg.method = 'POST';
msg.url = baseUrl + '/rest/v1/station_live?on_conflict=station_id';
msg.headers = {
  'apikey': key,
  'Authorization': 'Bearer ' + key,
  'Content-Type': 'application/json',
  'Prefer': 'resolution=merge-duplicates,return=minimal'
};
msg.payload = rows;
msg._loai = 'station_live';
return msg;

const p = msg.payload || {};
const id = Number(p.stationId);
const allowed = ['STOP', 'EMERGENCY_STOP'];
if (![1, 2, 3].includes(id) || !allowed.includes(String(p.command || ''))) return null;

msg.topic = 'station/' + id + '/command';
msg.payload = JSON.stringify({
  stationId: id,
  command: 'EMERGENCY_STOP',
  errorCode: 'E3',
  commandId: p.commandId || ('cmd-' + id + '-' + Date.now()),
  requestedAt: new Date().toISOString()
});
return msg;

// Chỉ chạy khi HTTP upsert station_live thành công
const code = Number(msg.statusCode || 0);
if (code < 200 || code >= 300) {
    return null;
}

const stations = global.get('evStations') || {};
const map = global.get('evStationMap') || {};
const baseUrl = String(env.get('SUPABASE_URL') || '')
    .replace(/\/+$/, '')
    .replace(/\/rest\/v1$/i, '');
const key = env.get('SUPABASE_SERVICE_ROLE_KEY');

if (!baseUrl || !key) return null;

const messages = [];
const now = Date.now();

for (let i = 1; i <= 3; i++) {
    const s = stations[i];
    if (!s) continue;

    const uuid = map[String(i)];
    if (!uuid) continue;

    const conn = String(s.connectionStatus || '').toUpperCase();
    const status = String(s.status || '').toUpperCase();

    const lastCallKey = 'lastCallNext_' + i;
    const lastCall = flow.get(lastCallKey) || 0;

    if (conn === 'ONLINE' && status === 'AVAILABLE') {
        if (now - lastCall >= 15000) {
            flow.set(lastCallKey, now);
            messages.push({
                method: 'POST',
                url: baseUrl + '/rest/v1/rpc/queue_call_next',
                headers: {
                    'apikey': key,
                    'Authorization': 'Bearer ' + key,
                    'Content-Type': 'application/json'
                },
                payload: { p_station_id: uuid },
                _stationNo: i,
                _rpc: 'queue_call_next'
            });
        }
    }

    const lastStartKey = 'lastStartServing_' + i;
    const lastStart = flow.get(lastStartKey) || 0;
    if (conn === 'ONLINE' && status === 'CHARGING') {
        if (now - lastStart >= 10000) {
            flow.set(lastStartKey, now);
            messages.push({
                method: 'POST',
                url: baseUrl + '/rest/v1/rpc/queue_start_serving',
                headers: {
                    'apikey': key,
                    'Authorization': 'Bearer ' + key,
                    'Content-Type': 'application/json'
                },
                payload: { p_station_id: uuid },
                _stationNo: i,
                _rpc: 'queue_start_serving'
            });
        }
    }
}

if (!messages.length) return null;

// Node-RED function: return array of messages → gửi tuần tự trên output 1
return messages;

// Khôi phục phiên IN_PROGRESS từ Supabase sau khi Node-RED khởi động.
const restore = global.get('evSessionsRestore');
if (restore && typeof restore === 'object') {
  const currentSessions = flow.get('evSessions') || {};
  for (const [key, value] of Object.entries(restore)) {
    if (!currentSessions[key]) currentSessions[key] = value;
  }
  flow.set('evSessions', currentSessions);
  global.set('evSessionsRestore', null);
}

if (!flow.get('tariffConfig')) {
  const shared = global.get('evTariffShared');
  if (shared) flow.set('tariffConfig', shared);
}

let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { node.warn('Session JSON không hợp lệ'); return null; }
}

const match = String(msg.topic || '').match(/^station\/([1-3])\/session$/);
if (!match || !p || typeof p !== 'object' || Array.isArray(p)) return null;

const stationId = Number(p.stationId || p.station_id || match[1]);
const sessionId = String(p.sessionId || p.session_code || p.sessionCode || '');
const sequence = Number(p.sequence);
const totalWh = Number(p.totalEnergyWh ?? p.total_energy_wh ?? p.energy_wh);

if (![1, 2, 3].includes(stationId) || !sessionId ||
    !Number.isFinite(sequence) || sequence < 1 ||
    !Number.isFinite(totalWh) || totalWh < 0) return null;

// ESP32 gửi Unix timestamp theo giây; Node-RED Date cần milliseconds.
function normalizeTimestamp(value) {
  if (value === undefined || value === null || value === '') return Date.now();
  if (typeof value === 'number' || /^\d+(\.\d+)?$/.test(String(value))) {
    const n = Number(value);
    return n < 1000000000000 ? Math.round(n * 1000) : Math.round(n);
  }
  const parsed = new Date(value).getTime();
  return Number.isFinite(parsed) ? parsed : Date.now();
}
const timestamp = normalizeTimestamp(p.timestamp ?? p.timestamp_ms ?? p.updatedAt);

const tariff = flow.get('tariffConfig') || {
  currency: 'VND', low: 0, normal: 0, peak: 0,
  lowStart: '00:00', lowEnd: '06:00',
  peakStart: '17:30', peakEnd: '22:30',
  version: 'CHUA_CAU_HINH'
};

const sessions = flow.get('evSessions') || {};
let current = sessions[stationId];
const incomingStatus = String(p.status || p.session_status || 'CHARGING').toUpperCase();

function isTerminal(status) {
  return ['COMPLETED', 'FINISHED', 'STOPPED', 'ENDED',
          'INTERRUPTED', 'FAILED', 'FAULT', 'CANCELLED'].includes(status);
}
function numOrNull(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}
function mapBandValues(source, fallback) {
  const x = source || {};
  return {
    low: Math.max(0, Number(x.low ?? fallback?.low) || 0),
    normal: Math.max(0, Number(x.normal ?? fallback?.normal) || 0),
    peak: Math.max(0, Number(x.peak ?? fallback?.peak) || 0)
  };
}

if (!current || current.sessionId !== sessionId) {
  current = {
    stationId,
    sessionId,
    startTime: p.startTime ? normalizeTimestamp(p.startTime) : timestamp,
    lastTime: timestamp,
    lastSequence: sequence,
    lastTotalWh: totalWh,
    energyWh: totalWh,
    energyByBand: mapBandValues(p.energyByBand || p.energy_by_band),
    costVnd: Math.max(0, Number(p.sessionCost ?? p.session_cost) || 0),
    costByBand: mapBandValues(p.costByBand || p.cost_by_band),
    status: incomingStatus,
    startSoc: numOrNull(p.startSoc ?? p.start_soc ?? p.soc),
    endSoc: numOrNull(p.endSoc ?? p.end_soc ?? p.soc),
    batteryCapacityKWh: numOrNull(p.batteryCapacityKWh ?? p.battery_capacity_kwh),
    durationSeconds: numOrNull(p.durationSeconds ?? p.duration_seconds),
    terminationReason: String(p.terminationReason || p.termination_reason || p.faultCode || p.fault_code || ''),
    tariffVersion: String(p.tariffVersion || p.tariff_version || tariff.version || ''),
    tariffVersions: [String(p.tariffVersion || p.tariff_version || tariff.version || '')].filter(Boolean),
    lastPowerW: Math.max(0, Number(p.powerW ?? p.power_w) || 0)
  };
  if (isTerminal(incomingStatus)) current.endTime = timestamp;
  sessions[stationId] = current;
  flow.set('evSessions', sessions);

  const ackList = [{ stationId, sessionId, sequence }];
  msg.payload = {
    type: 'session_update',
    stationId,
    sessionId,
    sequence,
    ackList,
    currentSessions: Object.values(sessions),
    history: flow.get('evSessionHistory') || [],
    tariff,
    updatedAt: Date.now()
  };
  return msg;
}

// Bản ghi có sequence đã xử lý: không tính lại điện năng/chi phí,
// nhưng vẫn upsert trạng thái hiện tại và gửi ACK để ESP32 bỏ bản ghi khỏi queue.
if (sequence <= Number(current.lastSequence || 0)) {
  node.status({ fill: 'yellow', shape: 'ring', text: 'Retry Seq ' + sequence + ' → ACK' });
  msg.payload = {
    type: 'session_update',
    stationId,
    sessionId,
    sequence,
    ackList: [{ stationId, sessionId, sequence }],
    currentSessions: Object.values(sessions),
    history: flow.get('evSessionHistory') || [],
    tariff,
    updatedAt: Date.now()
  };
  return msg;
}

const deltaWh = totalWh - Number(current.lastTotalWh || 0);
const from = Number(current.lastTime || 0);
const to = timestamp;
const durationMs = to - from;
const timestampIsOlder = durationMs < 0;
if (deltaWh < -0.001) {
  node.warn('Tổng Wh giảm bất thường: ' + sessionId);
  return null;
}

function parseMinutes(value, fallback) {
  const parts = String(value || fallback).split(':').map(Number);
  return parts[0] * 60 + parts[1];
}
function getVietnamClock(epochMs) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Ho_Chi_Minh',
    weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
  }).formatToParts(new Date(epochMs));
  const values = {};
  parts.forEach(part => { values[part.type] = part.value; });
  const dayMap = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return { minute: Number(values.hour) * 60 + Number(values.minute), day: dayMap[values.weekday] };
}
function inTimeRange(minute, start, end) {
  if (start === end) return false;
  if (start < end) return minute >= start && minute < end;
  return minute >= start || minute < end;
}
function getBand(epochMs) {
  const clock = getVietnamClock(epochMs);
  const lowStart = parseMinutes(tariff.lowStart, '00:00');
  const lowEnd = parseMinutes(tariff.lowEnd, '06:00');
  const peakStart = parseMinutes(tariff.peakStart, '17:30');
  const peakEnd = parseMinutes(tariff.peakEnd, '22:30');
  if (inTimeRange(clock.minute, lowStart, lowEnd)) return 'low';
  if (clock.day !== 0 && inTimeRange(clock.minute, peakStart, peakEnd)) return 'peak';
  return 'normal';
}
const rates = {
  low: Math.max(0, Number(tariff.low) || 0),
  normal: Math.max(0, Number(tariff.normal) || 0),
  peak: Math.max(0, Number(tariff.peak) || 0)
};

// Tính phần điện năng tăng thêm theo từng khoảng thời gian/khung giá.
if (deltaWh > 0 && durationMs > 0) {
  let cursor = from;
  while (cursor < to) {
    const nextMinute = Math.floor(cursor / 60000) * 60000 + 60000;
    const segmentEnd = Math.min(to, nextMinute);
    const segmentMs = segmentEnd - cursor;
    const segmentWh = deltaWh * (segmentMs / durationMs);
    const band = getBand(cursor + segmentMs / 2);
    current.energyByBand[band] += segmentWh;
    current.costByBand[band] += (segmentWh / 1000) * rates[band];
    cursor = segmentEnd;
  }
  current.costVnd = current.costByBand.low + current.costByBand.normal + current.costByBand.peak;
}

// Tong Wh tu ESP32 la bo dem tich luy co tham chieu; cap nhat truc tiep
// de khong cong trung. Neu timestamp bi lui, khong phan bo chi phi vao sai khung gio.
current.energyWh = totalWh;
if (timestampIsOlder) {
  node.warn('Seq moi nhung timestamp cu: ' + sessionId + ' / Seq ' + sequence +
    ' / incoming=' + timestamp + ' / current=' + from +
    '. Da ghi nhan tong Wh, khong phan bo tien cho khoang thoi gian nay.');
} else {
  current.lastTime = timestamp;
}
current.lastSequence = sequence;
current.lastTotalWh = totalWh;
current.lastPowerW = Math.max(0, Number(p.powerW ?? p.power_w) || 0);
current.status = incomingStatus;
current.endSoc = numOrNull(p.endSoc ?? p.end_soc ?? p.soc) ?? current.endSoc;
current.durationSeconds = numOrNull(p.durationSeconds ?? p.duration_seconds) ?? current.durationSeconds;
current.batteryCapacityKWh = numOrNull(p.batteryCapacityKWh ?? p.battery_capacity_kwh) ?? current.batteryCapacityKWh;
current.terminationReason = String(p.terminationReason || p.termination_reason || p.faultCode || p.fault_code || current.terminationReason || '');
const version = String(p.tariffVersion || p.tariff_version || tariff.version || '');
if (version && !current.tariffVersions.includes(version)) current.tariffVersions.push(version);
current.tariffVersion = current.tariffVersions.join(', ');

const ended = isTerminal(current.status);
if (ended) {
  current.endTime = timestamp;
  if (current.durationSeconds === null || current.durationSeconds === undefined) {
    current.durationSeconds = Math.max(0, Math.floor((timestamp - current.startTime) / 1000));
  }
}

sessions[stationId] = current;
flow.set('evSessions', sessions);

let history = flow.get('evSessionHistory') || [];
if (ended && !history.some(item => item.sessionId === sessionId && item.stationId === stationId)) {
  history.unshift({
    stationId,
    sessionId,
    startTime: current.startTime,
    endTime: timestamp,
    durationSeconds: current.durationSeconds,
    startSoc: current.startSoc,
    endSoc: current.endSoc,
    energyWh: current.energyWh,
    energyByBand: current.energyByBand,
    costVnd: Math.round(current.costVnd),
    costByBand: current.costByBand,
    status: current.status,
    terminationReason: current.terminationReason,
    tariffVersion: current.tariffVersion
  });
  history = history.slice(0, 100);
  flow.set('evSessionHistory', history);
}

msg.payload = {
  type: 'session_update',
  stationId,
  sessionId,
  sequence,
  ackList: [{ stationId, sessionId, sequence }],
  currentSessions: Object.values(sessions),
  history,
  tariff,
  updatedAt: Date.now()
};
return msg;

const m = String(msg.topic || '').match(/^station\/([1-3])\/queue$/);
if (!m) return null;
let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== 'object') return null;

const id = Number(p.stationId || p.station_id || m[1]);
const count = Math.max(0, Number(p.queueCount ?? p.waitingVehicles ?? p.queue_count) || 0);
const wait = Math.max(0, Number(p.estimatedWaitMinutes ?? p.waitMinutes ?? p.estimated_wait_minutes) || 0);
const entry = { stationId: id, queueCount: count, estimatedWaitMinutes: wait, updatedAt: Date.now() };

let q = flow.get('evQueue') || {};
q[id] = entry;
flow.set('evQueue', q);
global.set('evQueue', q);

msg.payload = { type: 'queue_update', queue: Object.values(q) };
return msg;

const m = String(msg.topic || '').match(/^station\/([1-3])\/ota\/status$/);
if (!m) return null;

let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); }
  catch (e) { p = { status: p }; }
}
if (!p || typeof p !== 'object' || Array.isArray(p)) p = {};

// Số trạm: 1, 2, 3
const stationId = Number(p.stationId || p.station_id || m[1]);

// UUID dùng cho Supabase
const stationUUIDMap = {
  1: '520509ac-9d18-49a3-ba7c-ad00f1a194ec',
  2: '9c100fbb-fc6d-424c-be6b-3c15731b80a6',
  3: '9a2f0053-dd1a-4b0d-99d1-2975f66ab72b'
};

const stationUUID = stationUUIDMap[stationId];

if (!stationUUID) {
  node.error('Không tìm thấy UUID cho trạm: ' + stationId, msg);
  return null;
}

const status = String(p.status || p.result || 'UNKNOWN').toUpperCase();
let version = String(p.version || p.firmwareVersion || p.firmware_version || '');
const commandId = String(p.commandId || p.command_id || flow.get('otaCommandId_' + stationId) || '');

if (status === 'SUCCESS') {
  const expected = flow.get('otaExpectedVersion_' + stationId);
  if (expected) version = String(expected);
  flow.set('otaExpectedVersion_' + stationId, null);
}

let rawProgress = p.downloadPercent;
if (rawProgress === undefined) rawProgress = p.progress;
if (rawProgress === undefined) rawProgress = p.percent;
if (rawProgress === undefined) rawProgress = p.download_percent;

let downloadPercent = null;
if (rawProgress !== undefined && rawProgress !== null && rawProgress !== '') {
  const n = Number(rawProgress);
  if (Number.isFinite(n)) downloadPercent = Math.max(0, Math.min(100, n));
}

const downloadedBytes = Number(p.downloadedBytes ?? p.downloaded_bytes);
const totalBytes = Number(p.totalBytes ?? p.total_bytes);

msg.payload = {
  type: 'ota_update',

  // Giữ số trạm để các Function cũ tiếp tục hoạt động
  stationId,

  // UUID riêng để ghi dữ liệu vào Supabase
  stationUUID,

  commandId,
  status,
  version,
  message: String(p.message || p.error || ''),
  downloadPercent,
  downloadedBytes: Number.isFinite(downloadedBytes) ? downloadedBytes : null,
  totalBytes: Number.isFinite(totalBytes) ? totalBytes : null,
  updatedAt: new Date().toISOString()
};

return msg;

const p = msg.payload || {};
const topic = String(msg.topic || '');

if (topic === 'admin/ui/ota') {
  const id = Number(p.stationId);
  const url = String(p.firmwareUrl || '');
  const version = String(p.version || '').trim();
  const sha256 = String(p.sha256 || '').trim().toLowerCase();
  const known = global.get('evStations') || {};
  const current = known[id];
  const stationMap = global.get('evStationMap') || {};

  // Lấy mã trạm từ số trạm
  const stationCode = stationMap[String(id)];

  // Từ mã trạm lấy UUID Supabase
  const stationUuid = stationCode
    ? stationMap[String(stationCode)]
    : null;

  // Kiểm tra UUID
  const uuidRegex =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  if (!uuidRegex.test(String(stationUuid || ''))) {
    node.warn(
      'OTA bị từ chối: UUID không hợp lệ cho trạm ' +
      id + ', stationCode=' + stationCode
    );
    return null;
  }

  if (![1, 2, 3].includes(id) || !stationUuid || !/^https:\/\//i.test(url)) {
    node.warn('OTA bị từ chối: station hoặc Signed URL không hợp lệ');
    return null;
  }
  if (!version || !/^[a-f0-9]{64}$/.test(sha256)) {
    node.warn('OTA bị từ chối: cần version và SHA-256 64 ký tự');
    return null;
  }
  if (!current || String(current.connectionStatus).toUpperCase() !== 'ONLINE') {
    node.warn('OTA bị từ chối: trạm không ONLINE');
    return null;
  }
  if (['CHARGING', 'FAULT'].includes(String(current.status).toUpperCase())) {
    node.warn('OTA bị từ chối: trạm đang sạc hoặc đang FAULT');
    return null;
  }

  const baseUrl = String(env.get('SUPABASE_URL') || '').replace(/\/+$/, '').replace(/\/rest\/v1$/i, '');
  const key = env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!baseUrl || !key) {
    node.error('Thiếu SUPABASE_URL hoặc SUPABASE_SERVICE_ROLE_KEY', msg);
    return null;
  }

  const commandId = 'ota-' + id + '-' + Date.now();
  flow.set('otaExpectedVersion_' + id, version);
  flow.set('otaCommandId_' + id, commandId);

  const command = {
    stationId: id,
    command: 'UPDATE',
    commandId,
    version,
    firmwareUrl: url,
    sha256,
    requestedAt: new Date().toISOString()
  };

  const jobMsg = {
    method: 'POST',
    url: baseUrl + '/rest/v1/ota_jobs?on_conflict=command_id',
    headers: {
      'apikey': key,
      'Authorization': 'Bearer ' + key,
      'Content-Type': 'application/json',
      'Prefer': 'resolution=ignore-duplicates,return=minimal'
    },
    payload: [{
      station_id: stationUuid,
      command_id: commandId,
      status: 'PENDING'
    }],
    _otaCommand: command,
    _otaStationId: id
  };
  return [jobMsg, null, null];
}

if (topic === 'admin/ui/tariff') {
  return [null, null, { topic: 'admin/tariff/config', payload: p }];
}
return null;

if (msg.topic === 'admin/tariff/init') {
  const existing = flow.get('tariffConfig') || global.get('evTariffShared');
  if (existing) {
    flow.set('tariffConfig', existing);
    msg.payload = { type: 'tariff_update', tariff: existing };
    return [msg, null];
  }
}

const p = msg.payload || {};
const names = ['low', 'normal', 'peak'];
const cfg = {};
for (const name of names) {
  const value = Number(p[name]);
  if (!Number.isFinite(value) || value < 0 || value > 100000) return null;
  cfg[name] = value;
}

function validTime(value, fallback) {
  const text = String(value || fallback);
  return /^([01]\d|2[0-3]):[0-5]\d$/.test(text) ? text : fallback;
}

cfg.currency = 'VND';
cfg.lowStart = validTime(p.lowStart, '00:00');
cfg.lowEnd = validTime(p.lowEnd, '06:00');
cfg.peakStart = validTime(p.peakStart, '17:30');
cfg.peakEnd = validTime(p.peakEnd, '22:30');
cfg.version = 'ADMIN-' + Date.now();
cfg.updatedAt = new Date().toISOString();
cfg.source = 'admin';

flow.set('tariffConfig', cfg);
global.set('evTariffShared', cfg);

const map = global.get('evStationMap') || {};
const byStation = global.get('evTariff') || {};
for (const no of ['1', '2', '3']) {
  byStation[no] = {
    currency: cfg.currency,
    low: cfg.low,
    normal: cfg.normal,
    peak: cfg.peak,
    lowStart: cfg.lowStart,
    lowEnd: cfg.lowEnd,
    peakStart: cfg.peakStart,
    peakEnd: cfg.peakEnd,
    updatedAt: cfg.updatedAt,
    stationId: map[no] || (byStation[no] && byStation[no].stationId) || null
  };
}
global.set('evTariff', byStation);

// Gửi xuống từng ESP32
const messages = [];
for (const no of [1, 2, 3]) {
  messages.push({
    topic: 'station/' + no + '/tariff',
    payload: JSON.stringify({
      stationId: no,
      currency: cfg.currency,
      low: cfg.low,
      normal: cfg.normal,
      peak: cfg.peak,
      lowStart: cfg.lowStart,
      lowEnd: cfg.lowEnd,
      peakStart: cfg.peakStart,
      peakEnd: cfg.peakEnd,
      version: cfg.version,
      updatedAt: cfg.updatedAt
    }),
    qos: 1
  });
}

msg.payload = { type: 'tariff_update', tariff: cfg };
return [msg, messages];

const tariff = (msg.payload && msg.payload.tariff) ? msg.payload.tariff : null;
if (!tariff || typeof tariff !== 'object') return null;

const map = global.get('evStationMap') || {};
const baseUrl = String(env.get('SUPABASE_URL') || '').replace(/\/+$/, '').replace(/\/rest\/v1$/i, '');
const key = env.get('SUPABASE_SERVICE_ROLE_KEY');
if (!baseUrl || !key) return null;

const now = tariff.updatedAt || new Date().toISOString();
const rows = [];
for (const n of ['1', '2', '3']) {
  const stationId = map[n];
  if (!stationId) continue;
  rows.push({
    station_id: stationId,
    currency: String(tariff.currency || 'VND'),
    low_price: Math.max(0, Number(tariff.low) || 0),
    normal_price: Math.max(0, Number(tariff.normal) || 0),
    peak_price: Math.max(0, Number(tariff.peak) || 0),
    low_start: String(tariff.lowStart || '00:00'),
    low_end: String(tariff.lowEnd || '06:00'),
    peak_start: String(tariff.peakStart || '17:30'),
    peak_end: String(tariff.peakEnd || '22:30'),
    updated_at: now
  });
}
if (!rows.length) return null;

msg.method = 'POST';
msg.url = baseUrl + '/rest/v1/station_tariffs?on_conflict=station_id';
msg.headers = {
  'apikey': key,
  'Authorization': 'Bearer ' + key,
  'Content-Type': 'application/json',
  'Prefer': 'resolution=merge-duplicates,return=representation'
};
msg.payload = rows;
msg._loai = 'station_tariffs';
msg._so_ban_ghi = rows.length;
return msg;

const p = msg.payload || {};

if (p.type !== 'session_update') return null;

const map = global.get('evStationMap') || {};

const baseUrl = String(env.get('SUPABASE_URL') || '')
    .replace(/\/+$/, '')
    .replace(/\/rest\/v1$/i, '');

const key = env.get('SUPABASE_SERVICE_ROLE_KEY');

if (!baseUrl || !key) {
    node.error('Thiếu SUPABASE_URL hoặc SUPABASE_SERVICE_ROLE_KEY', msg);
    return null;
}

// Lấy cả phiên hiện tại và lịch sử
const currentSessions = Array.isArray(p.currentSessions)
    ? p.currentSessions : [];

const history = Array.isArray(p.history)
    ? p.history : [];

// Gộp và loại trùng theo sessionId.
// Nếu cùng phiên có dữ liệu đang chạy và đã hoàn tất,
// ưu tiên bản ghi có trạng thái kết thúc.
const sessionMap = new Map();

function isTerminal(status) {
    return [
        'COMPLETED', 'FINISHED', 'STOPPED',
        'ENDED', 'CANCELLED', 'FAILED',
        'FAULT', 'INTERRUPTED'
    ].includes(String(status || '').toUpperCase());
}

for (const s of [...currentSessions, ...history]) {
    if (!s || !s.sessionId) continue;

    const id = String(s.sessionId);
    const old = sessionMap.get(id);

    if (!old) {
        sessionMap.set(id, s);
        continue;
    }

    if (!isTerminal(old.status) && isTerminal(s.status)) {
        sessionMap.set(id, { ...old, ...s });
    } else {
        sessionMap.set(id, { ...s, ...old });
    }
}

const rows = [];

for (const s of sessionMap.values()) {
    const stationNo = String(
        s.stationId !== undefined && s.stationId !== null
            ? s.stationId
            : p.stationId
    );

    // Ánh xạ stationId -> stationCode -> UUID
    const stationCode = map[stationNo];
    const uuid = map[String(stationCode)];

    if (
        !uuid ||
        !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(uuid)
    ) {
        node.error(
            'Không ánh xạ được UUID cho trạm ' + stationNo +
            ', stationCode=' + stationCode +
            ', session=' + s.sessionId,
            msg
        );
        return null;
    }

    const raw = String(s.status || 'CHARGING').toUpperCase();

    let dbStatus = 'IN_PROGRESS';

    if (['COMPLETED', 'FINISHED', 'STOPPED', 'ENDED'].includes(raw)) {
        dbStatus = 'COMPLETED';
    } else if (raw === 'CANCELLED') {
        dbStatus = 'CANCELLED';
    } else if (['FAILED', 'FAULT', 'INTERRUPTED'].includes(raw)) {
        dbStatus = 'FAILED';
    }

    const ended = dbStatus !== 'IN_PROGRESS';

    const startMs = Number(s.startTime) || Date.now();
    const endMs = ended
        ? (Number(s.endTime) || (
            Number(s.lastTime) || Date.now()
        ))
        : null;

    const startIso = new Date(startMs).toISOString();
    const endIso = endMs ? new Date(endMs).toISOString() : null;

    const duration = Number.isFinite(Number(s.durationSeconds))
        ? Math.max(0, Math.floor(Number(s.durationSeconds)))
        : Math.max(
            0,
            Math.floor(((endMs || Date.now()) - startMs) / 1000)
        );

    const energyBand = s.energyByBand || {};
    const costBand = s.costByBand || {};

    rows.push({
        station_id: uuid,
        session_code: String(s.sessionId),
        status: dbStatus,
        started_at: startIso,
        ended_at: endIso,
        energy_consumed_wh: Math.max(0, Number(s.energyWh) || 0),
        duration_seconds: duration,
        total_cost: Math.max(0, Number(s.costVnd) || 0),
        currency: 'VND',

        energy_low_wh: Math.max(0, Number(energyBand.low) || 0),
        energy_normal_wh: Math.max(0, Number(energyBand.normal) || 0),
        energy_peak_wh: Math.max(0, Number(energyBand.peak) || 0),

        cost_low: Math.max(0, Number(costBand.low) || 0),
        cost_normal: Math.max(0, Number(costBand.normal) || 0),
        cost_peak: Math.max(0, Number(costBand.peak) || 0),

        tariff_version: String(s.tariffVersion || ''),
        last_sequence: Number(s.lastSequence) || 0,
        last_total_wh: Number(s.lastTotalWh) || 0,

        start_soc: s.startSoc === null || s.startSoc === undefined
            ? null : Number(s.startSoc),

        end_soc: s.endSoc === null || s.endSoc === undefined
            ? null : Number(s.endSoc),

        battery_capacity_kwh:
            s.batteryCapacityKWh === null ||
            s.batteryCapacityKWh === undefined
                ? null : Number(s.batteryCapacityKWh),

        termination_reason: ended
            ? (
                String(s.terminationReason || '') ||
                (dbStatus === 'FAILED' ? raw : null)
            )
            : null,

        updated_at: new Date().toISOString()
    });
}

if (!rows.length) {
    node.warn('Không có phiên sạc hợp lệ để đồng bộ');
    return null;
}

// Giữ ACK hiện tại, chỉ gửi sau khi Supabase ghi thành công
msg._ackList = Array.isArray(p.ackList) ? p.ackList : [];

msg.method = 'POST';
msg.url = baseUrl +
    '/rest/v1/charging_sessions?on_conflict=station_id,session_code';

msg.headers = {
    'apikey': key,
    'Authorization': 'Bearer ' + key,
    'Content-Type': 'application/json',
    'Prefer': 'resolution=merge-duplicates,return=minimal'
};

msg.payload = rows;
msg._loai = 'charging_sessions';

node.status({
    fill: 'blue',
    shape: 'dot',
    text: rows.length + ' phiên chờ đồng bộ'
});

return msg;

const code = Number(msg.statusCode || 0);
const ackList = msg._ackList || [];

if (code >= 200 && code < 300) {
    node.status({
        fill: 'green',
        shape: 'dot',
        text: 'sessions OK ' + code
    });

    if (ackList.length > 0) {
        const messages = [];

        for (const item of ackList) {
            messages.push({
                topic: 'station/' + item.stationId + '/ack',
                payload: JSON.stringify({
                    session_id: item.sessionId,
                    sequence: item.sequence,
                    status: 'SYNCED'
                }),
                qos: 1
            });
        }

        return [null, messages];
    }

    return null;
}

// Ghi nhận nội dung lỗi thực tế từ Supabase
let errorBody = msg.payload;

if (typeof errorBody !== 'string') {
    try {
        errorBody = JSON.stringify(errorBody);
    } catch (e) {
        errorBody = String(errorBody);
    }
}

node.status({
    fill: 'red',
    shape: 'ring',
    text: 'sessions ' + code
});

node.warn(
    'charging_sessions HTTP ' + code +
    ' → Không gửi ACK. Supabase response: ' +
    String(errorBody || '').slice(0, 2000)
);

return null;

const p = msg.payload || {};
const stationId = Number(p.stationId);
if (p.type !== 'ota_update' || ![1,2,3].includes(stationId)) return null;

const map = global.get('evStationMap') || {};

const stationUuid = String(
  p.stationUUID || map[String(stationId)] || ''
).trim();

const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!uuidRegex.test(stationUuid)) {
  node.error(
    'Station UUID không hợp lệ. stationId=' + stationId +
    ', stationUUID=' + stationUuid,
    msg
  );
  return null;
}
const baseUrl = String(env.get('SUPABASE_URL') || '').replace(/\/+$/, '').replace(/\/rest\/v1$/i, '');
const key = env.get('SUPABASE_SERVICE_ROLE_KEY');
if (!stationUuid || !baseUrl || !key) {
  node.warn('OTA status chưa ghi được: thiếu station map hoặc Supabase env');
  return null;
}

const now = new Date().toISOString();
const status = String(p.status || 'UNKNOWN').toUpperCase();
const commandId = String(p.commandId || flow.get('otaCommandId_' + stationId) || '');

const statusRow = {
  station_id: stationUuid,
  hardware_model: 'ESP32',
  last_ota_status: status,
  last_reported_at: now,
  updated_at: now
};
if (status === 'SUCCESS' && p.version) {
  statusRow.current_version = String(p.version);
  statusRow.last_success_at = now;
}
const statusMsg = {
  method: 'PATCH',
  url: baseUrl + '/rest/v1/ota_device_status?station_id=eq.' + encodeURIComponent(stationUuid),
  headers: {
    'apikey': key, 'Authorization': 'Bearer ' + key,
    'Content-Type': 'application/json', 'Prefer': 'return=minimal'
  },
  payload: statusRow
};

let stationMsg = null;
if (status === 'SUCCESS' && p.version) {
  stationMsg = {
    method: 'PATCH',
    url: baseUrl + '/rest/v1/stations?id=eq.' + encodeURIComponent(stationUuid),
    headers: {
      'apikey': key, 'Authorization': 'Bearer ' + key,
      'Content-Type': 'application/json', 'Prefer': 'return=minimal'
    },
    payload: { firmware_version: String(p.version), updated_at: now }
  };
}

let jobMsg = null;
if (commandId) {
  const dbStatusMap = {
    RECEIVED: 'ACCEPTED',
    DOWNLOADING: 'DOWNLOADING',
    VERIFYING: 'VERIFYING',
    UPDATING: 'INSTALLING',
    INSTALLING: 'INSTALLING',
    REBOOTING: 'REBOOTING',
    SUCCESS: 'SUCCESS',
    FAILED: 'FAILED'
  };
  const dbStatus = dbStatusMap[status];
  if (dbStatus) {
    const jobPatch = { status: dbStatus };
    if (status === 'RECEIVED') jobPatch.started_at = now;
    if (['SUCCESS', 'FAILED'].includes(status)) jobPatch.finished_at = now;
    if (status === 'FAILED') jobPatch.error_message = String(p.message || 'OTA failed');
    if (status === 'SUCCESS') jobPatch.error_message = null;
    jobMsg = {
      method: 'PATCH',
      url: baseUrl + '/rest/v1/ota_jobs?command_id=eq.' + encodeURIComponent(commandId),
      headers: {
        'apikey': key, 'Authorization': 'Bearer ' + key,
        'Content-Type': 'application/json', 'Prefer': 'return=minimal'
      },
      payload: jobPatch
    };
  }
}
return [statusMsg, stationMsg, jobMsg];

const code = Number(msg.statusCode || 0);
if (code < 200 || code >= 300) {
  node.error('Không tạo được ota_jobs. Không gửi lệnh OTA. HTTP ' + code, msg);
  return null;
}
const command = msg._otaCommand;
const stationId = Number(msg._otaStationId);
if (!command || ![1,2,3].includes(stationId)) return null;
return {
  topic: 'station/' + stationId + '/ota/command',
  qos: 1,
  retain: false,
  payload: JSON.stringify(command)
};

const supabaseUrl = String(env.get('SUPABASE_URL') || '')
    .replace(/\/+$/, '')
    .replace(/\/rest\/v1$/, '');
const serviceKey = String(env.get('SUPABASE_SERVICE_ROLE_KEY') || '');

if (!supabaseUrl || !serviceKey) {
    node.error('Thiếu SUPABASE_URL hoặc SUPABASE_SERVICE_ROLE_KEY trong Environment Variables.', msg);
    return null;
}

msg.method = 'GET';
msg.url = supabaseUrl + '/rest/v1/stations?select=id,station_code,name,address,latitude,longitude,is_active&order=station_code.asc';
msg.headers = {
    'apikey': serviceKey,
    'Authorization': 'Bearer ' + serviceKey,
    'Accept': 'application/json'
};

return msg;

const status = Number(msg.statusCode || 0);

if (status < 200 || status >= 300) {
    node.error('Supabase trả về HTTP ' + status, msg);
    return null;
}

const rows = msg.payload;

if (!Array.isArray(rows)) {
    node.error('Dữ liệu Supabase không phải một mảng stations.', msg);
    return null;
}

const meta = {};
const stationMap = {};

for (const row of rows) {
    if (!row || !row.station_code || !row.id) continue;
    if (row.is_active === false) continue;

    const code = String(row.station_code).trim().toUpperCase();
    const match = code.match(/(\d+)$/);

    if (!match) continue;

    const no = Number(match[1]);
    if (!Number.isFinite(no)) continue;

    meta[String(no)] = {
        stationId: row.id,
        stationCode: code,
        name: row.name || ('Trạm sạc ' + String(no).padStart(2, '0')),
        address: row.address || null,
        latitude: row.latitude === null ? null : Number(row.latitude),
        longitude: row.longitude === null ? null : Number(row.longitude),
        isActive: row.is_active
    };

    // Bản đồ mã trạm sang UUID và số trạm
    stationMap[code] = row.id;
    stationMap[String(no)] = code;
}

global.set('evStationMeta', meta);
global.set('evStationMap', stationMap);

msg.payload = {
    success: true,
    message: 'Đồng bộ danh sách trạm thành công.',
    stationCount: Object.keys(meta).length,
    stations: Object.values(meta).map(s => ({
        stationCode: s.stationCode,
        stationId: s.stationId,
        name: s.name,
        latitude: s.latitude,
        longitude: s.longitude
    })),
    syncedAt: new Date().toISOString()
};

return msg;

msg.headers = msg.headers || {};
msg.headers['Access-Control-Allow-Origin'] = '*';
msg.headers['Access-Control-Allow-Methods'] = 'GET,POST,OPTIONS';
msg.headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization';
msg.headers['Content-Type'] = 'application/json; charset=utf-8';

const method = String(msg.req && msg.req.method || '').toUpperCase();

if (method === 'OPTIONS') {
    msg.statusCode = 204;
    msg.payload = '';
    return [null, msg];
}

return [msg, null];

/*
 * FUNCTION: XỬ LÝ API NGƯỜI DÙNG
 * OUTPUT 1: HTTP Response
 * OUTPUT 2: HTTP Request Supabase RPC
 * Hỗ trợ JOIN / CANCEL / SNAPSHOT theo RPC queue_*
 */

const url = String(
    msg.req &&
    (msg.req.originalUrl || msg.req.url || msg.req.path) || ''
);

const method = String(
    msg.req && msg.req.method || 'GET'
).toUpperCase();

const path = url.split('?')[0].replace(/\/+$/, '');
const parts = path.split('/').filter(Boolean);

const idx = parts.indexOf('stations');

const hasStationId =
    idx >= 0 &&
    /^\d+$/.test(parts[idx + 1] || '');

const stationId = hasStationId
    ? Number(parts[idx + 1])
    : null;

const sub = hasStationId
    ? (parts[idx + 2] || null)
    : null;

const isStationList =
    idx >= 0 &&
    idx === parts.length - 1;

const validStationIds = [1, 2, 3];

function coordinate(value) {
    if (value === undefined || value === null || value === '') {
        return null;
    }
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function stationPublic(no) {
    const meta = (global.get('evStationMeta') || {})[String(no)] || {};
    const live = (global.get('evStations') || {})[no] || {};

    const queues = global.get('evQueue') || {};
    const q = queues[no] || queues[String(no)] || {};

    const tariffs = global.get('evTariff') || {};
    const tariff =
        tariffs[String(no)] ||
        global.get('evTariffShared') ||
        {};

    const conn = String(
        live.connectionStatus || 'UNKNOWN'
    ).toUpperCase();

    const op = String(
        live.status || 'UNKNOWN'
    ).toUpperCase();

    let display = 'UNKNOWN';

    if (conn === 'OFFLINE') {
        display = 'OFFLINE';
    } else if (conn === 'ONLINE') {
        if (op === 'CHARGING') display = 'CHARGING';
        else if (op === 'FAULT') display = 'FAULT';
        else if (op === 'AVAILABLE') display = 'AVAILABLE';
    }

    return {
        id: Number(no),
        code: meta.stationCode || ('ST00' + no),
        name: meta.name ||
            ('Trạm sạc ' + String(no).padStart(2, '0')),
        status: display,
        connectionStatus: conn,
        operatingStatus: op,
        latitude: coordinate(meta.latitude),
        longitude: coordinate(meta.longitude),
        queueCount: q.queueCount ?? 0,
        estimatedWaitMinutes: q.estimatedWaitMinutes ?? 0,
        tariff: {
            currency: tariff.currency || 'VND',
            low: tariff.low ?? 0,
            normal: tariff.normal ?? 0,
            peak: tariff.peak ?? 0,
            lowStart: tariff.lowStart || '00:00:00',
            lowEnd: tariff.lowEnd || '06:00:00',
            peakStart: tariff.peakStart || '17:30:00',
            peakEnd: tariff.peakEnd || '22:30:00'
        },
        updatedAt: live.lastSeen || null
    };
}

function sendError(status, error, message) {
    msg.statusCode = status;
    msg.payload = {
        success: false,
        ok: false,
        error: error,
        message: message
    };
    return [msg, null];
}

function getStationUuid(stationNo) {
    const meta = (global.get('evStationMeta') || {})[String(stationNo)] || {};
    return meta.stationId || meta.station_id || meta.id || meta.uuid || null;
}

function getSupabaseConfig() {
    const supabaseUrl = String(env.get('SUPABASE_URL') || '')
        .replace(/\/+$/, '')
        .replace(/\/rest\/v1$/i, '');
    const serviceKey = String(env.get('SUPABASE_SERVICE_ROLE_KEY') || '');
    return { supabaseUrl, serviceKey };
}

// CORS + JSON
msg.headers = Object.assign({}, msg.headers, {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    'Content-Type': 'application/json; charset=utf-8'
});

// Chỉ xử lý API thuộc /api/user/stations
if (
    idx < 0 ||
    parts[0] !== 'api' ||
    parts[1] !== 'user'
) {
    return sendError(
        404,
        'ENDPOINT_NOT_FOUND',
        'Không tìm thấy API.'
    );
}

// ==========================================
// POST - JOIN hoặc CANCEL hàng chờ
// ==========================================
if (
    method === 'POST' &&
    hasStationId &&
    sub === 'queue'
) {
    if (!validStationIds.includes(stationId)) {
        return sendError(
            404,
            'STATION_NOT_FOUND',
            'Không tìm thấy trạm.'
        );
    }

    const body = msg.payload || {};
    const action = String(body.action || 'JOIN').toUpperCase();
    const guestId = String(body.guestId || '').trim();

    const uuidRegex =
        /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

    if (!uuidRegex.test(guestId)) {
        return sendError(
            400,
            'INVALID_GUEST_ID',
            'guestId không hợp lệ.'
        );
    }

    if (action !== 'JOIN' && action !== 'CANCEL') {
        return sendError(
            400,
            'INVALID_ACTION',
            'action phải là JOIN hoặc CANCEL.'
        );
    }

    const stationUuid = getStationUuid(stationId);
    if (!stationUuid) {
        return sendError(
            404,
            'STATION_UUID_NOT_FOUND',
            'Không tìm thấy UUID trạm trong dữ liệu đồng bộ.'
        );
    }

    // Kiểm tra trạng thái trạm trước khi JOIN
    if (action === 'JOIN') {
        const live = (global.get('evStations') || {})[stationId] || {};
        const conn = String(live.connectionStatus || '').toUpperCase();
        const op = String(live.status || '').toUpperCase();
        if (conn === 'OFFLINE') {
            return sendError(409, 'STATION_OFFLINE', 'Trạm đang mất kết nối, không thể đăng ký hàng chờ.');
        }
        if (op === 'FAULT') {
            return sendError(409, 'STATION_FAULT', 'Trạm đang lỗi, không thể đăng ký hàng chờ.');
        }
    }

    const { supabaseUrl, serviceKey } = getSupabaseConfig();
    if (!supabaseUrl || !serviceKey) {
        return sendError(
            500,
            'SERVER_CONFIGURATION_ERROR',
            'Node-RED chưa cấu hình Supabase.'
        );
    }

    const rpcName = (action === 'CANCEL') ? 'queue_cancel' : 'queue_join';

    msg.method = 'POST';
    msg.url = supabaseUrl + '/rest/v1/rpc/' + rpcName;
    msg.headers = {
        'Content-Type': 'application/json',
        'apikey': serviceKey,
        'Authorization': 'Bearer ' + serviceKey
    };
    // CANCEL cần p_entry_id + p_guest_id; JOIN cần p_station_id + p_guest_id
    if (action === 'CANCEL') {
        const entryId = String(body.entryId || body.queueId || body.entry_id || body.queue_id || '').trim();
        const uuidRegex2 = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
        if (!uuidRegex2.test(entryId)) {
            return sendError(
                400,
                'INVALID_ENTRY_ID',
                'Hủy hàng chờ cần entryId (UUID của lượt chờ).'
            );
        }
        msg.payload = {
            p_entry_id: entryId,
            p_guest_id: guestId
        };
    } else {
        msg.payload = {
            p_station_id: stationUuid,
            p_guest_id: guestId
        };
    }

    msg._queueAction = action;
    msg._stationNo = stationId;
    msg._guestId = guestId;
    msg._queueGet = false;

    return [null, msg];
}

// ==========================================
// GET - SNAPSHOT hàng chờ (có guestId)
// ==========================================
if (
    method === 'GET' &&
    hasStationId &&
    sub === 'queue'
) {
    if (!validStationIds.includes(stationId)) {
        return sendError(
            404,
            'STATION_NOT_FOUND',
            'Không tìm thấy trạm.'
        );
    }

    const query = (msg.req && msg.req.query) ? msg.req.query : {};
    const guestId = String(query.guestId || '').trim();

    const stationUuid = getStationUuid(stationId);
    if (!stationUuid) {
        return sendError(
            404,
            'STATION_UUID_NOT_FOUND',
            'Không tìm thấy UUID trạm.'
        );
    }

    const { supabaseUrl, serviceKey } = getSupabaseConfig();
    if (!supabaseUrl || !serviceKey) {
        return sendError(
            500,
            'SERVER_CONFIGURATION_ERROR',
            'Node-RED chưa cấu hình Supabase.'
        );
    }

    msg.method = 'POST';
    msg.url = supabaseUrl + '/rest/v1/rpc/queue_snapshot';
    msg.headers = {
        'Content-Type': 'application/json',
        'apikey': serviceKey,
        'Authorization': 'Bearer ' + serviceKey
    };
    msg.payload = {
        p_station_id: stationUuid,
        p_guest_id: guestId || null
    };

    msg._queueGet = true;
    msg._stationNo = stationId;
    msg._guestId = guestId;

    return [null, msg];
}

// ==========================================
// GET - DANH SÁCH TRẠM
// ==========================================
if (
    method === 'GET' &&
    isStationList &&
    parts.length === 3
) {
    msg.statusCode = 200;
    msg.payload = {
        stations: validStationIds.map(stationPublic),
        serverTime: new Date().toISOString()
    };
    return [msg, null];
}

// ==========================================
// GET - GIÁ SẠC
// ==========================================
if (
    method === 'GET' &&
    hasStationId &&
    sub === 'tariff' &&
    parts.length === 5
) {
    const tariffs = global.get('evTariff') || {};
    const tariff =
        tariffs[String(stationId)] ||
        global.get('evTariffShared') ||
        {};

    msg.statusCode = 200;
    msg.payload = {
        stationId: stationId,
        currency: tariff.currency || 'VND',
        low: tariff.low ?? 0,
        normal: tariff.normal ?? 0,
        peak: tariff.peak ?? 0,
        lowStart: tariff.lowStart || '00:00:00',
        lowEnd: tariff.lowEnd || '06:00:00',
        peakStart: tariff.peakStart || '17:30:00',
        peakEnd: tariff.peakEnd || '22:30:00',
        updatedAt: tariff.updatedAt || null
    };
    return [msg, null];
}

// ==========================================
// GET - CHI TIẾT TRẠM
// ==========================================
if (
    method === 'GET' &&
    hasStationId &&
    !sub &&
    parts.length === 4
) {
    msg.statusCode = 200;
    msg.payload = stationPublic(stationId);
    return [msg, null];
}

// ==========================================
// PHƯƠNG THỨC / ENDPOINT KHÔNG HỢP LỆ
// ==========================================
return sendError(
    405,
    'METHOD_NOT_ALLOWED',
    'Endpoint hoặc phương thức HTTP không được hỗ trợ.'
);

msg.headers = Object.assign({}, msg.headers, {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    'Content-Type': 'application/json; charset=utf-8'
});

const status = Number(msg.statusCode || 500);

let data = msg.payload;

if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        data = null;
    }
}

// ==========================================
// 1. GET - KẾT QUẢ SNAPSHOT
// ==========================================
if (msg._queueGet === true) {

    if (status < 200 || status >= 300) {
        msg.statusCode = 502;
        msg.payload = {
            success: false,
            ok: false,
            error: 'QUEUE_READ_FAILED',
            message: 'Không thể đọc dữ liệu hàng chờ.'
        };
        return msg;
    }

    const result = (data && typeof data === 'object' && !Array.isArray(data))
        ? data
        : (Array.isArray(data) ? (data[0] || {}) : {});

    const stationNo = Number(msg._stationNo);

    const queueCount = Math.max(0, Number(
        result.queueCount ?? result.queue_count ?? 0
    ));
    const estimatedWaitMinutes = Math.max(0, Number(
        result.estimatedWaitMinutes ?? result.estimated_wait_minutes ?? 0
    ));
    const updatedAt = result.updatedAt || result.updated_at || new Date().toISOString();

    // Cập nhật bộ nhớ tạm Node-RED
    const queues = global.get('evQueue') || {};
    queues[String(stationNo)] = {
        queueCount: queueCount,
        estimatedWaitMinutes: estimatedWaitMinutes,
        updatedAt: updatedAt
    };
    global.set('evQueue', queues);

    msg.statusCode = 200;
    msg.payload = {
        success: true,
        stationId: stationNo,
        guestId: msg._guestId || null,
        queueId: result.queueId || result.queue_id || result.id || null,
        status: result.status || result.entry_status || 'WAITING',
        position: result.position ?? result.pos ?? null,
        queueCount: queueCount,
        estimatedWaitMinutes: estimatedWaitMinutes,
        message: result.message || 'Tra cứu hàng chờ thành công'
    };
    return msg;
}

// ==========================================
// 2. POST - KẾT QUẢ JOIN / CANCEL
// ==========================================
if (status >= 200 && status < 300) {

    const result = (data && typeof data === 'object' && !Array.isArray(data))
        ? data
        : (Array.isArray(data) ? (data[0] || {}) : {});

    const action = msg._queueAction || 'JOIN';
    const stationNo = Number(msg._stationNo);

    if (stationNo > 0) {
        const queues = global.get('evQueue') || {};
        queues[String(stationNo)] = {
            queueCount: Number(result.queueCount ?? result.queue_count ?? 0),
            estimatedWaitMinutes: Number(
                result.estimatedWaitMinutes ?? result.estimated_wait_minutes ?? 0
            ),
            updatedAt: result.joinedAt || result.updatedAt || result.updated_at || new Date().toISOString()
        };
        global.set('evQueue', queues);
    }

    msg.statusCode = 200;
    msg.payload = {
        success: true,
        action: action,
        queueId: result.queueId || result.queue_id || result.id || null,
        status: result.status || (action === 'CANCEL' ? 'CANCELLED' : 'WAITING'),
        position: result.position ?? result.pos ?? null,
        queueCount: Number(result.queueCount ?? result.queue_count ?? 0),
        estimatedWaitMinutes: Number(
            result.estimatedWaitMinutes ?? result.estimated_wait_minutes ?? 0
        ),
        message: result.message || (
            action === 'CANCEL'
                ? 'Hủy hàng chờ thành công'
                : 'Đăng ký hàng chờ thành công'
        )
    };
    return msg;
}

// ==========================================
// 3. XỬ LÝ LỖI
// ==========================================
msg.statusCode = status >= 400 ? status : 500;

let errMsg = 'Không thể xử lý yêu cầu hàng chờ.';
let errCode = 'QUEUE_REQUEST_FAILED';

if (data && typeof data === 'object') {
    if (data.message) errMsg = data.message;
    if (data.error) {
        errCode = (typeof data.error === 'string') ? data.error : errCode;
        if (!data.message && data.error) errMsg = String(data.error);
    }
}

msg.payload = {
    success: false,
    ok: false,
    error: errCode,
    message: errMsg
};
return msg;

msg.headers = msg.headers || {};
msg.headers['Access-Control-Allow-Origin'] = '*';
msg.headers['Access-Control-Allow-Methods'] = 'GET,POST,OPTIONS';
msg.headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization';
msg.headers['Content-Type'] = 'application/json; charset=utf-8';
msg.statusCode = 502;
msg.payload = {
    ok: false,
    error: 'SUPABASE_CONNECTION_ERROR',
    message: msg.error && msg.error.message ? msg.error.message : 'Không thể kết nối Supabase.'
};
return msg;

const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_SERVICE_ROLE_KEY');
if (!url || !key) {
  node.error('Thiếu SUPABASE_URL hoặc SUPABASE_SERVICE_ROLE_KEY', msg);
  return null;
}
const baseUrl = url.replace(/\/+$/, '').replace(/\/rest\/v1$/i, '');
msg.method = 'GET';
msg.url = baseUrl + '/rest/v1/stations?select=id,station_code,is_active';
msg.headers = {
  'apikey': key,
  'Authorization': 'Bearer ' + key,
  'Accept': 'application/json'
};
return msg;
